class AdversarialConcurrent(unittest.TestCase):
    def test_second_export_mid_run_different_data(self):
        tmp = tempfile.TemporaryDirectory(); self.addCleanup(tmp.cleanup)
        p = Path(tmp.name) / "out.csv"
        inner = [Order(9, "Inner customer with a much longer name", Decimal("9.00"), date(2026, 9, 9))] * 3
        outer_rows = [Order(1, "Outer", Decimal("1.00"), date(2026, 9, 1))] * 2
        class Orders:
            def __iter__(self_):
                yield outer_rows[0]
                write_csv(inner, p)
                yield outer_rows[1]
        err = None
        try:
            write_csv(Orders(), p)
        except OSError as e:
            err = e
        content = p.read_bytes()
        good = {b"id,customer,total,placed_on\r\n" + b"9,Inner customer with a much longer name,9.00,2026-09-09\r\n" * 3,
                b"id,customer,total,placed_on\r\n" + b"1,Outer,1.00,2026-09-01\r\n" * 2}
        self.assertIn(content, good, f"err={err!r} content={content!r}")
EOF
